SELECT



    c.is_deleted = 0

        AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR sk.spec_text LIKE CONCAT('%', #{q.keyword}, '%'))


        AND c.user_id = #{q.userId}


        AND c.category_id = #{q.categoryId}


        AND c.store_id = #{q.storeId}


        AND c.selected = #{q.selected}


        AND c.create_time >= #{q.beginTime}


        AND c.create_time <= #{q.endTime}


ORDER BY c.id DESC
